window.RESEARCH_TERMS = {"version":1,"title":"Terms","policy":"main-terms-only","entries":[{"id":"foundations-research","topic":"foundations","term":"Research","aliases":[],"definitions":[{"text":"Research is an ORGANIZED and SYSTEMATIC way of FINDING ANSWERS to QUESTIONS","sources":[{"sourceId":"methods","pages":[17]}]},{"text":"Research is a careful, critical, disciplined inquiry, varying in techniques and methods according to the nature and conditions of the problem, directed towards clarification or resolution of the problem (Good,1972 )","sources":[{"sourceId":"methods","pages":[17]}],"label":"Good (1972)"},{"text":"Research is a process of gathering data or information to solve a particular or specific problem in a scientific manner (Manuel and Medel,1976 )","sources":[{"sourceId":"methods","pages":[17]}],"label":"Manuel and Medel (1976)"},{"text":"Research is an attempt to gain solution to the problems, a collection of data in a rigorously controlled situation for the purpose of prediction or explanation (Treece and Treece, 1973)","sources":[{"sourceId":"methods","pages":[17]}],"label":"Treece and Treece (1973)"},{"text":"Research is a systematic study or investigation of something for the purpose of answering questions posed by the researcher (Sanchez, 1980)","sources":[{"sourceId":"methods","pages":[17]}],"label":"Sanchez (1980)"},{"text":"Research is a mobilizing force, not just an academic prerequisite.","sources":[{"sourceId":"architecture","pages":[2]}]}],"details":[{"label":"The Method / The Action / The Output","text":"The Method\nSystematic, disciplined, scientific, and empirical inquiry.\n\nThe Action\nSearching, validating, refining, and generating.\n\nThe Output\nObjective knowledge, truth, and evidence.\n\nTo mobilize society, inform action, and translate into policy/practice.","sources":[{"sourceId":"architecture","pages":[2]}]},{"label":"Importance of Research","text":"To serve man and provide a good life\nDiscover more facts about unknown phenomena\nFind answer to the problems by existing methods and information\nImprove existing techniques and develop new instruments or products\nDiscover unrecognized substance\nDiscover pathways of action\nOrder related, valid generalization into systematized science\nProvide basis for decision making\nTo satisfy researcher’s curiosity\nTo find answers to queries\nAcquire better and deeper understanding\nTo expand and verify existing knowledge\nImproves efficiency, efficacy and quality\nImproves exportations of goods\nRespond to economic recovery & austerity","sources":[{"sourceId":"methods","pages":[18]}]},{"label":"Qualities of Good Researcher","text":"Research oriented\nEfficient\nScientific\nEffective\nActive\nResourceful\nCreative\nHonest\nEconomical\nReligious","sources":[{"sourceId":"methods","pages":[20]}]},{"label":"Classification of Research","text":"PURPOSE\nPredictive Research\nDirective Research\nIlluminative Research\n\nGOAL\nBasic or Pure Research\nApplied Research\n\nLEVELS OF INVESTIGATION\nExploratory\nDescriptive\nExperimental\n\nTYPE OF ANALYSIS\nAnalytic\nHolistic\n\nSCOPE\nAction Research\n\nCHOICE OF ANSWER\nEvaluation\nDevelopmental\n\nSTATISTICAL CONTENT\nQuantitative\nNon-Quantitative\n\nTIME ELEMENT\nHistorical\nDescriptive\nExperimental","sources":[{"sourceId":"methods","pages":[21]}]},{"label":"Professional Goals","text":"Produce evidence-based practice\nEstablish professional credibility\nObserve accountability for actions\nPromote cost-effectiveness via documentation","sources":[{"sourceId":"architecture","pages":[4]}]},{"label":"Research Process","text":"1 PROBLEM/OBJECTIVES\n2 THEORITICAL/CONCEPTUAL FRAMEWORK\n3 ASSUMPTIONS\n4 HYPOTHESIS\n5 REVIEW OF RELATED LITERATURE\n6 RESEARCH DESIGN\n7 DATA COLLECTION\n8 DATA PROCESSING\n9 STATISTICAL TREATMENT\n10 ANALYSIS & INTERPRETATION\n11 SUMMARY/CONCLUSION/RECOMMENDATION","sources":[{"sourceId":"methods","pages":[25]}]},{"label":"The Research Process — flowchart labels","text":"Identification and Definition of a Research Problem\nStatement of Research Problem/Objectives\nTheoretical/Conceptual Framework Formulation\nOperational Definition of Variables\nHypothesis Formulation\nChoosing Appropriate Research Design\nIdentification of Target Population and Sampling\nData Collection\nPreparation of Research Instrument\nReliability Testing and Validation\nQ Administration, Interview, Testing & Observation\nQuality Control\nData Processing\n(Editing, Coding, Encoding, Creation of Data Files Tabulation)\nData Analysis and Interpretation\n(Statistical Analysis, Interpretation, Generalization)\nReport Preparation and Information Dissemination","sources":[{"sourceId":"methods","pages":[26]}]}]},{"id":"foundations-empirical","topic":"foundations","term":"Empirical","aliases":["EMPERICAL"],"definitions":[{"text":"Direct experience or observation","sources":[{"sourceId":"methods","pages":[19]}],"label":"EMPERICAL"},{"text":"Rooted in hard evidence and real-life observation","sources":[{"sourceId":"architecture","pages":[3]}]}],"details":[]},{"id":"foundations-logical","topic":"foundations","term":"Logical","aliases":[],"definitions":[{"text":"Valid procedure and principles","sources":[{"sourceId":"methods","pages":[19]}]}],"details":[]},{"id":"foundations-cyclical","topic":"foundations","term":"Cyclical","aliases":[],"definitions":[{"text":"Starts with problem & ends with problem","sources":[{"sourceId":"methods","pages":[19]}]}],"details":[]},{"id":"foundations-analytical","topic":"foundations","term":"Analytical","aliases":[],"definitions":[{"text":"Utilizes proven analytical procedures","sources":[{"sourceId":"methods","pages":[19]}]}],"details":[]},{"id":"foundations-critical","topic":"foundations","term":"Critical","aliases":[],"definitions":[{"text":"Exhibits careful and precise judgment","sources":[{"sourceId":"methods","pages":[19]}]},{"text":"Withstands scrutiny and actively questions its own claims.","sources":[{"sourceId":"architecture","pages":[3]}]}],"details":[]},{"id":"foundations-methodical","topic":"foundations","term":"Methodical","aliases":[],"definitions":[{"text":"Uses systematic method and procedures","sources":[{"sourceId":"methods","pages":[19]}]}],"details":[]},{"id":"foundations-replicability","topic":"foundations","term":"Replicability","aliases":[],"definitions":[{"text":"Repeated to arrive at valid and conclusive results","sources":[{"sourceId":"methods","pages":[19]}]}],"details":[]},{"id":"foundations-controlled","topic":"foundations","term":"Controlled","aliases":[],"definitions":[{"text":"Minimizes effects of extraneous variables.","sources":[{"sourceId":"architecture","pages":[3]}]}],"details":[]},{"id":"foundations-transparent","topic":"foundations","term":"Transparent","aliases":[],"definitions":[{"text":"Methods, assumptions, and data are stated explicitly.","sources":[{"sourceId":"architecture","pages":[3]}]}],"details":[]},{"id":"foundations-rigorous","topic":"foundations","term":"Rigorous","aliases":[],"definitions":[{"text":"Procedures are relevant, appropriate, and justified.","sources":[{"sourceId":"architecture","pages":[3]}]}],"details":[]},{"id":"foundations-systematic","topic":"foundations","term":"Systematic","aliases":[],"definitions":[{"text":"Follows a logical sequence; deliberate and planned.","sources":[{"sourceId":"architecture","pages":[3]}]}],"details":[]},{"id":"foundations-valid-verifiable","topic":"foundations","term":"Valid & Verifiable","aliases":[],"definitions":[{"text":"Findings are correct and reproducible by others.","sources":[{"sourceId":"architecture","pages":[3]}]}],"details":[]},{"id":"variables-variable","topic":"variables","term":"Variable","aliases":[],"definitions":[{"text":"Defined as quantity susceptible of fluctuations of change in value or magnitude under different conditions (Calmorin, 2007)","sources":[{"sourceId":"methods","pages":[22]}]},{"text":"A quality or characteristics that two or more mutually exclusive values or properties ( Sevilla et. All, 2002)","sources":[{"sourceId":"methods","pages":[22]}]}],"details":[]},{"id":"variables-independent","topic":"variables","term":"Independent Variable","aliases":["IV"],"definitions":[{"text":"This is a stimulus variables which chosen by the researcher to determine its relationship to an observe phenomena","sources":[{"sourceId":"methods","pages":[23]}]}],"details":[{"label":"Examples","text":"Mathematics Scores and Number of Hours Study in Mathematics as Perceived by Sophomore Secondary Students in Private Schools in Cebu City\n\nNumber of Hours → Age, gender, socio-economic, attitudes towards study → Mathematics scores\n\nWeight Increment of Grouper Cultured in Fish Cages using Pellets and Bread Meal as Supplemental Feeds.\n\nPellets of Bread Meal → Salinity Oxygen Temperature, ph → Weight Increment","sources":[{"sourceId":"methods","pages":[24]}]}]},{"id":"variables-dependent","topic":"variables","term":"Dependent Variable","aliases":["DV"],"definitions":[{"text":"This is a response variable which is observed and measured to determine the effect of the independent variables.","sources":[{"sourceId":"methods","pages":[23]}]}],"details":[]},{"id":"variables-intervening","topic":"variables","term":"Intervening Variable","aliases":[],"definitions":[{"text":"This variable intrudes or interferes with the IV and DV but its effects can either reinforce or weaken the IV and DV.","sources":[{"sourceId":"methods","pages":[23]}]}],"details":[]},{"id":"variables-control","topic":"variables","term":"Control Variable","aliases":[],"definitions":[{"text":"This variable controlled by the researcher in which the effects can be neutralized by eliminating or removing the variable.","sources":[{"sourceId":"methods","pages":[23]}]}],"details":[]},{"id":"variables-moderator","topic":"variables","term":"Moderator Variable","aliases":[],"definitions":[{"text":"This is secondary or special type of variable chosen by the researcher to determine if it alters or modifies the relationships between the independent and dependent variables.","sources":[{"sourceId":"methods","pages":[23]}]}],"details":[]},{"id":"problems-research-problem","topic":"problems","term":"Research Problem","aliases":[],"definitions":[{"text":"Problem is any (1) significant, perplexing and challenging situation, real or artificial, the solution of which requires reflective thinking (2) a perplexing situation after it has been translated into a question or series of questions that help determine the direction of subsequent inquiry Dewey as cited by Good ( ).","sources":[{"sourceId":"methods","pages":[31,32]}]},{"text":"A problem that someone would like to research. A problem that a person finds unsatisfactory or unsettling, a difficulty of some sort, a state of affairs that needs to be change.","sources":[{"sourceId":"methods","pages":[31,32]}]}],"details":[{"label":"Characteristics of Research Problem","text":"Novelty\nInteresting\nRelevant\nFeasible\nResearchable (SMART)\nEthical\nSystematic","sources":[{"sourceId":"methods","pages":[34]}]},{"label":"Sources of Research Problems (Calmorin & Calmorin, 2007)","text":"Specialization of the researcher\nThe field of speicalization of the researcher is an impetus towards conduct of research\n\nCxurrent and Past Researches\nCurrent and past are rich sources of RP\n\nRecommendations from Theses and research journals\n\nOriginal and creative ideas of the researcher based on problems met in locality","sources":[{"sourceId":"methods","pages":[35]}]},{"label":"Guideline in the selection of research problem","text":"The research problem or topic must be chosen by the researcher himself.\nIt must be within the interest of the researcher.\nIt must be within the specialization of the researcher.\nIt must be within the competence of the researcher to tackle.\nIt must be within the ability of the researcher to finance; otherwise he must be able to find funding for research.\nIt is researcher and manageable that is,","sources":[{"sourceId":"methods","pages":[36]}]},{"label":"WHY?","text":"Aim or purpose of the problem for investigation","sources":[{"sourceId":"methods","pages":[33]}]},{"label":"WHAT?","text":"The subject matter or topic to be investigated.","sources":[{"sourceId":"methods","pages":[33]}]},{"label":"WHERE?","text":"The place or locale where the research is to be conducted.","sources":[{"sourceId":"methods","pages":[33]}]},{"label":"WHEN?","text":"The period or time of the study during the data are to be gathered.","sources":[{"sourceId":"methods","pages":[33]}]},{"label":"WHO?","text":"Population or universe from whom the data are to be collected","sources":[{"sourceId":"methods","pages":[33]}]},{"label":"Statement of Research Problem/Objectives","text":"Research problem and research objectives have the same characteristics but they differ in form because the former is stated in interrogative or question form and the latter, in declarative form.","sources":[{"sourceId":"methods","pages":[41]}]},{"label":"Formulating research problem","text":"The general statement of the problem and the specific sub-problems or questions should be formulated first before conducting the research.\nIt is customary to state specific sub-problems (specific questions) in the interrogative form.\nEach specific questions must be clear and unequivocal (one meaning)\nEach specific question is researchable apart from the other questions, which are answers to specific questions can be found even without considering the other questions.\nEach question must be based upon known facts and phenomena.\nAnswers to each specific question can be interpreted apart from the answers to other specific questions.\nAnswers to each specific question must contribute to the development of the whole research problem or topic.\nSumming up the answers to all specific questions will give a complete development of the entire study\nThe number of specific questions should be enough to cover the development of the whole research problem or study.\nThere should be a general statement of the problem and then should be broken up into as many sub-problems or specific questions as necessary","sources":[{"sourceId":"methods","pages":[37]}]},{"label":"Research Title","text":"It must grab the attention and makes you want to read further\nIt must be intriguing, thought-provoking\nIt must include the 5Ws\nIt must be brief and concise with a maximum of 20 words and writen in inverted pyramid and in capital letters\nIt must avoid a study of, an investigation of , an analysis,,,\nIt must follow the format required by institution.","sources":[{"sourceId":"methods","pages":[38]}]}]},{"id":"frameworks-hypothesis","topic":"frameworks","term":"Hypothesis","aliases":["Research hypothesis"],"definitions":[{"text":"is defined as a wise guess that is formulated and temporarily adopted to explain the observed facts covered by the study.","sources":[{"sourceId":"methods","pages":[42]}]},{"text":"The researcher hypothesis is a predicative statement that relates an independent variable to dependent variable.","sources":[{"sourceId":"methods","pages":[75]}]}],"details":[],"relatedTopics":["designs"]},{"id":"frameworks-null","topic":"frameworks","term":"Null Hypothesis","aliases":[],"definitions":[{"text":"is a denial of an existence of a trait, characteristic, quality, value, correlation or difference of the result.","sources":[{"sourceId":"methods","pages":[42]}]}],"details":[]},{"id":"frameworks-alternative","topic":"frameworks","term":"Alternative Hypothesis","aliases":[],"definitions":[{"text":"is an affirmation of the existence of the observed phenomenon.","sources":[{"sourceId":"methods","pages":[42]}]}],"details":[]},{"id":"frameworks-theoretical","topic":"frameworks","term":"Theoretical Framework","aliases":[],"definitions":[{"text":"shapes the justification of the research problem/research objectives in order to provide the legal basis for defining its parameters","sources":[{"sourceId":"methods","pages":[43]}]}],"details":[],"clarification":{"text":"A theoretical framework normally grounds the study in relevant theory and its assumptions. A legal basis is a separate justification, not a defining requirement of a theoretical framework.","references":[{"title":"USC Libraries: theoretical framework","url":"https://libguides.usc.edu/writingguide/theoreticalframework"}]},"practiceExcludedReason":"The only supplied definition conflates theoretical grounding with a legal basis. Retain the source quotation and verified clarification; do not score this misconception."},{"id":"frameworks-conceptual-framework","topic":"frameworks","term":"Conceptual Framework","aliases":[],"definitions":[{"text":"presents specific and well-defined concepts which are called constructs.","sources":[{"sourceId":"methods","pages":[44]}]}],"details":[]},{"id":"frameworks-assumptions","topic":"frameworks","term":"Assumptions","aliases":[],"definitions":[{"text":"are presumed to be true statements of facts related to the research problem.","sources":[{"sourceId":"methods","pages":[45]}]}],"details":[]},{"id":"frameworks-significance","topic":"frameworks","term":"Significance of the Study","aliases":[],"definitions":[{"text":"Is presented comprehensively to convince the screening committee the importance of the study.","sources":[{"sourceId":"methods","pages":[46]}]}],"details":[]},{"id":"frameworks-scope","topic":"frameworks","term":"Scope and Limitations of the Study","aliases":[],"definitions":[{"text":"This includes the coverage of the study area, the subjects, the research apparatus, equipment or instrument, the research issues and concerns, the duration of the study, and the constraints that have direct bearing on the result of the study.","sources":[{"sourceId":"methods","pages":[47,49]}]}],"details":[]},{"id":"frameworks-conceptual-definition","topic":"frameworks","term":"Conceptual Definition","aliases":["constitutive"],"definitions":[{"text":"The definition are based on concepts or hypothetic ones which are usually taken from a dictionary, encyclopedia and published journals.","sources":[{"sourceId":"methods","pages":[48]}]},{"text":"also known as constitutive, is that which is given in dictionaries. It is the academic or universal meaning attributed to a word or group of works. Moreover, it is mostly abstract and formal in nature.","sources":[{"sourceId":"methods","pages":[67]}]}],"details":[]},{"id":"frameworks-operational-definition","topic":"frameworks","term":"Operational Definition","aliases":["functional"],"definitions":[{"text":"The definition of terms are based on observable characteristics and how it is used in the study.","sources":[{"sourceId":"methods","pages":[48]}]},{"text":"also known as functional. Operational definition may be measured and experimental. The measured operational definition states the way the concept is measured in the investigation. In an experimental operational definition the researcher may spell out the details of the manipulation of a variable.","sources":[{"sourceId":"methods","pages":[68]}]}],"details":[]},{"id":"instruments-validity","topic":"instruments","term":"Validity","aliases":[],"definitions":[{"text":"It means the degree to which a test or measuring instrument measures what it intends to measure.","sources":[{"sourceId":"methods","pages":[27]}]}],"details":[]},{"id":"instruments-content-validity","topic":"instruments","term":"Content validity","aliases":[],"definitions":[{"text":"It means the extent to which the content or topics of the test is truly representative of the content of the course.","sources":[{"sourceId":"methods","pages":[27]}]}],"details":[]},{"id":"instruments-concurrent-validity","topic":"instruments","term":"Concurrent validity","aliases":[],"definitions":[{"text":"It is the degree to which the test agrees or correlates with a criterion set up as an acceptable measure.","sources":[{"sourceId":"methods","pages":[27]}]}],"details":[]},{"id":"instruments-predictive-validity","topic":"instruments","term":"Predictive validity","aliases":[],"definitions":[{"text":"It is determined by showing how well predictions made from the test are confirmed by evidence gathered at some subsequent time.","sources":[{"sourceId":"methods","pages":[27]}]}],"details":[]},{"id":"instruments-construct-validity","topic":"instruments","term":"Construct validity","aliases":[],"definitions":[{"text":"It is the extent to which the test measures a theoretical construct or trait.","sources":[{"sourceId":"methods","pages":[27]}]}],"details":[]},{"id":"instruments-reliability","topic":"instruments","term":"Reliability","aliases":[],"definitions":[{"text":"It means the extent to which a research instrument is dependable, consistent and stable.","sources":[{"sourceId":"methods","pages":[28]}]}],"details":[{"label":"Excellent","text":"r ≥ 0.90\nHigh-stakes diagnostic decisions.","sources":[{"sourceId":"reliability","pages":[11]}]},{"label":"Good","text":"0.80 ≤ r < 0.90\nClassroom grading and certification.","sources":[{"sourceId":"reliability","pages":[11]}]},{"label":"Acceptable","text":"0.70 ≤ r < 0.80\nFormative tests and research surveys.","sources":[{"sourceId":"reliability","pages":[11]}]},{"label":"Questionable","text":"r < 0.70\nRequires item revision or test lengthening.","sources":[{"sourceId":"reliability","pages":[11]}]}]},{"id":"instruments-usability","topic":"instruments","term":"Usability","aliases":[],"definitions":[{"text":"It means the degree to which the research instrument be satisfactorily used by teachers, researchers, supervisors and school managers without expenditures of time, money and effect.","sources":[{"sourceId":"methods","pages":[29]}]}],"details":[{"label":"Base of administration","text":"To facilitate the administration of a research instrument, instruction should be complete and precise.","sources":[{"sourceId":"methods","pages":[29]}]},{"label":"Base of scoring","text":"It depends on the following aspects:\nConstruction of a test in the objective type.\nAnswer keys are adequately prepared.\nScoring directions are fully understood.","sources":[{"sourceId":"methods","pages":[29]}]},{"label":"Ease of interpretation and application","text":"Results of test are easy to interpret and apply if tables are provided.","sources":[{"sourceId":"methods","pages":[29]}]},{"label":"Low cost","text":"It is more practical if the test is low cost material-wise.","sources":[{"sourceId":"methods","pages":[29]}]},{"label":"Proper mechanical make-up","text":"A good research instrument should be printed clearly in an appropriate size for the grade or year level for which the instrument is intended.","sources":[{"sourceId":"methods","pages":[29]}]}]},{"id":"literature-related-literature","topic":"literature","term":"Related Literature","aliases":[],"definitions":[{"text":"Related literature is composed of discussions of facts and principles to which the present study is related.\n\nThe materials are usually printed and found in books, encyclopedias, professional journals, magazines, newspapers, and other publications.","sources":[{"sourceId":"methods","pages":[51]}]},{"text":"It is a section in a research paper, thesis dissertation, and research project in which the sources are taken from books, journals, magazines, novels, poetry, etc that contains facts, laws, theories and other documented observations. This is in a chronological order from recent to past when presented. It is unscientific if related literature are presented and of no explanation at the relevance to the present study.","sources":[{"sourceId":"methods","pages":[63]}]}],"details":[{"label":"Importance, purpose and functions","text":"Reviewed literature and studies help or guide the researcher in the following ways:\nHelp or guide the researcher in searching for or selecting a better research problem or topic.\nHelp the investigator understand his topic for research better.\nEnsure that there will be no duplication of other studies.\nHelp and guide the researcher in locating more sources of related information.\nHelp and guide the researcher in making his research design especially in\na. The formulation of specific questions to be researched on;\nb. The formulation of assumptions and hypotheses if there should be any;\nc. The formulation of conceptual framework;\nd. The selection and application of the methods of research;\ne. The selection and application of sampling technique;\nf. The selection and/ or preparation and validation of research instruments for gathering data;\ng. The selection and application of statistical procedures;\nh. The analysis, organization, presentation, and interpretation of data;\ni. The making of the summary of findings, conclusions, and recommendations; and\nHelp and guide the researcher in making comparison between his findings with the findings of other researchers on similar studies with the end in view of formulating generalizations or principles which are the contributions of the study to the fund of knowledge.","sources":[{"sourceId":"methods","pages":[52,53,54]}]},{"label":"Characteristics of related literature","text":"The surveyed materials must be as recent as possible\nExceptions:\nA. Treatises that deal on universals or things of more or less permanent nature may still be good today.\nB. When a comparison or contrast is to be made between the conditions of today and those of a remote past, say ten or twenty years ago.\nMaterials reviewed must be objective and unbiased.\nMaterials surveyed must be relevant to the study.\nSurveyed materials must have been based upon genuinely original and true facts or data to make valid and reliable.\nReviewed materials must not be too few or too many.","sources":[{"sourceId":"methods","pages":[55,56]}]},{"label":"Sources and where to locate sources","text":"Literature reviewed typically includes scholarly journals, scholarly books, authoritative databases and primary sources. Sometimes it includes newspapers, magazines, other books, films, and audio and video tapes, and other secondary sources.\n\nGenerally, the sources of related literature and studies are located in the following places:\nLibraries, either government, school, or private libraries.\nGovernment and private offices.\nThe National Library.\nThe library of the Department of Education, Culture and Sports.\nThe last two are especially rich depositories of related materials, particularly unpublished master’s thesis and doctoral dissertations.","sources":[{"sourceId":"methods","pages":[57,60]}]},{"label":"Example and explanation of the related literature","text":"Example:\n\nMurray’s (1998) article on nurse executives’ leadership roles stated that chief nursing officers (CNO) leave their position due to lack of power conflict with chief executive officer (CEO), and inadequate nursing personnel. [Related literature by Bruce P. Murray. 1998. “Nurse Executives’ Leadership Roles.” Journal of Nursing Administration. 28(6):48. (June 1998)].\n\nThe article of Murray has bearing to the present study because staff nurses’ performance would be affected if the middle managers or chief nursing officers have conflict with the chief executive officer or top manager and with problems met related to their job, for instance, inadequate nursing personnel. (EXPLANATION OF THE RELATED LITERATURE)","sources":[{"sourceId":"methods","pages":[64]}]}]},{"id":"literature-primary","topic":"literature","term":"Primary sources","aliases":["Primary Source"],"definitions":[{"text":"Primary sources are the origin of information under study, fundamental documents relating to a particular subject or idea. Often they are first hand accounts written by a witness or researcher at the time of an event or discovery.","sources":[{"sourceId":"methods","pages":[58]}]},{"text":"Is one prepared by an individual who was a participant in or a direct witness to the event being described.","sources":[{"sourceId":"methods","pages":[84]}]}],"details":[{"label":"Examples as printed on the slide","text":"E.g. published books, magazines, encyclopedias, almanacs and etc.","sources":[{"sourceId":"methods","pages":[58]}]},{"label":"Primary source examples","text":"1. A nineteenth-century teacher’s account of what it was like to live with a frontier family.\n2. A photograph of an eight-grade graduating class in 1930.\n3. Essays written by students in response to the question, “What do you like most and least about school?”\n4. Minutes of a school board meeting taken by the secretary of the board.\n5. Songs composed by members of a high school glee club.","sources":[{"sourceId":"methods","pages":[85]}]}],"clarification":{"text":"Source status depends on the evidence and research question, not publication format. Encyclopedias commonly synthesize earlier evidence. The same deck gives more useful firsthand/secondhand examples on pages 84-85.","references":[{"title":"Library of Congress: primary and secondary sources","url":"https://ask.loc.gov/faq/303148"}]},"relatedTopics":["historical"]},{"id":"literature-secondary","topic":"literature","term":"Secondary sources","aliases":["Secondary Source"],"definitions":[{"text":"Secondary sources are documents or recordings that relate to or discuss information originally presented elsewhere.","sources":[{"sourceId":"methods","pages":[59]}]},{"text":"Is a documents prepared by an individual who was not a direct witness to an event, but obtained his or her description of the event from someone else.","sources":[{"sourceId":"methods","pages":[84]}]}],"details":[{"label":"Examples as printed on the slide","text":"E.g. Information from the internet, unpublished thesis and dissertations","sources":[{"sourceId":"methods","pages":[59]}]},{"label":"Secondary source examples","text":"1. An encyclopedia describing various types of educational research conducted over a 10-year period.\n2. A magazine article summarizing Aristotle’s views on education.\n3. A student’s report to her counselor of why her teacher said she was being suspended from school.\n4. A book describing schooling in the New England colonies during the 1700s.\n5. A newspaper account of a school board meeting based on oral interviews with members of the board.","sources":[{"sourceId":"methods","pages":[85]}]}],"clarification":{"text":"Being online or unpublished does not determine whether a source is primary or secondary. An original thesis can report primary research; online collections can preserve firsthand records. Classify by the role of the evidence.","references":[{"title":"Library of Congress: primary and secondary sources","url":"https://ask.loc.gov/faq/303148"}]},"relatedTopics":["historical"]},{"id":"literature-legal","topic":"literature","term":"Related Legal Bases","aliases":[],"definitions":[{"text":"Related – means the legal bases, literature and studies which have direct bearing or relation to the present study.\n\nIt determine the relevance of the study to the government’s thrusts. The major sources of related legal bases are laws and department directives such as circulars, orders, memoranda, and others which are related to the present study.","sources":[{"sourceId":"methods","pages":[61]}]}],"details":[{"label":"Example and explanation of the legal basis","text":"Example:\n\nRepublic Act No. 7164 known as the “Philippine Nursing Act of 1991” defines professional nursing as the performance for a fee, salary, or other reward or compensation… toward the promotion of health, and alleviation of suffering through utilization of nursing process. (LEGAL BASIS).\n\nThe foregoing professional nursing definition explicitly expressed that nurses practice their profession for a fee or salary commensurate with their work in order to satisfy their needs and wants to cope with the fast changing world. In other words, the performance of a particular job affects nurses’ values especially if nurses meet the problems related to their job in the hospital, hence, promotion of health services cannot be attained. (EXPLANATION OF THE LEGAL BASIS)","sources":[{"sourceId":"methods","pages":[62]}]}]},{"id":"literature-related-studies","topic":"literature","term":"Related Studies (Local or Foreign)","aliases":["local studies","foreign studies"],"definitions":[{"text":"Published and unpublished research studies are sources of materials that are included in this section. The research studies which have direct bearing to the present study are segregated into foreign and local studies.","sources":[{"sourceId":"methods","pages":[65]}]}],"details":[{"label":"Example of local study","text":"Example of LOCAL STUDY:\n\nIn 1999, Sultan in her study on perceived sources of stress among staff nurses at a tertiary hospital in Quezon City, found out that lack of administrative support and no rewards were perceived by staff nurses as the most stressing… (Related local study by Vilma Sultan. 1999. “Perceived Sources of Stress Among Staff Nurses at Tertiary Hospital in Quezon City.” MA Thesis in Nursing. Central Philippine University, Iloilo City, Philippines.)\n\nSultan’s study has bearing to the present study because lack of administrative support, no rewards, and no opportunities for career development are among the job-related problems met by staff nurses in private and government hospitals in Iloilo City which block their way to perform effectively and efficiently. (EXPLANATION OF THE RELATED STUDY)","sources":[{"sourceId":"methods","pages":[66]}]}]},{"id":"designs-research-design","topic":"designs","term":"Research Design","aliases":[],"definitions":[{"text":"Task of defining the research problem is the preparation of the research project, popularly known as the “research design\".\nDecisions regarding what, where, when, how much, by what means concerning an inquiry or a research study constitute a research design.","sources":[{"sourceId":"methods","pages":[70]}]},{"text":"A research design is the arrangement of conditions for collection and analysis of data in a manner that aims to combine relevance to the research purpose with economy in procedure.","sources":[{"sourceId":"methods","pages":[71]}]},{"text":"Blueprint of the study. It guides the collection, measurement and analysis of data","sources":[{"sourceId":"methods","pages":[71]}]},{"text":"A plan or structure of the investigation in order to obtain answers to research questions. It outline what the researcher would like to do until the final analysis of the data","sources":[{"sourceId":"methods","pages":[71]}]}],"details":[{"label":"Features of Good RS","text":"A research design appropriate for a particular research problem, usually involves the following features.\nThe mean of obtaining information.\nThe availability and skills of the researcher and his staff, if any.\nThe objective of the problem to be studied.\nThe nature of the problem to be studied .\nThe availability of time and money for the research work.","sources":[{"sourceId":"methods","pages":[73]}]}]},{"id":"designs-sampling","topic":"designs","term":"Sampling Design","aliases":[],"definitions":[{"text":"Which deals with the methods of selecting items to be observed for the study.","sources":[{"sourceId":"methods","pages":[72]}]}],"details":[]},{"id":"designs-observational","topic":"designs","term":"Observational design","aliases":[],"definitions":[{"text":"Which relates to the condition under which the observation are to be create","sources":[{"sourceId":"methods","pages":[72]}]}],"details":[]},{"id":"designs-statistical","topic":"designs","term":"Statistical Design","aliases":[],"definitions":[{"text":"Which concern the question of the of How the information and data gathered are to be analyzed ?","sources":[{"sourceId":"methods","pages":[72]}]}],"details":[]},{"id":"designs-operational","topic":"designs","term":"Operational design","aliases":[],"definitions":[{"text":"Which deals techniques by which the procedures satisfied in sampling .","sources":[{"sourceId":"methods","pages":[72]}]}],"details":[],"practiceExcludedReason":"The supplied description is fragmentary and does not unambiguously explain operational design.","sourceNote":"The printed sentence is fragmentary. It is reproduced as supplied, without an invented completion."},{"id":"designs-hypothesis-testing","topic":"designs","term":"Hypothesis-testing research","aliases":["hypothesis testing research"],"definitions":[{"text":"When the purpose of research is to test a research hypothesis, it us termed as hypothesis testing research .It can be experimental or non-experimental","sources":[{"sourceId":"methods","pages":[75]}]},{"text":"hypothesis-testing research studies known as experimental studies are those researcher tests the hypothesis of casual relationship between variables.","sources":[{"sourceId":"methods","pages":[76]}]}],"details":[]},{"id":"designs-control-group","topic":"designs","term":"Control group","aliases":[],"definitions":[{"text":"When a group is exposed to usual conditions, it is termed as a control group.","sources":[{"sourceId":"methods","pages":[75]}]}],"details":[]},{"id":"designs-experimental-group","topic":"designs","term":"Experimental group","aliases":[],"definitions":[{"text":"But when the group is exposed to be some special condition, it is termed as Experimental group","sources":[{"sourceId":"methods","pages":[75]}]}],"details":[]},{"id":"designs-treatments","topic":"designs","term":"Treatments","aliases":["treatment"],"definitions":[{"text":"The different conditions under which Experiment and control groups are put up usually referred to as treatment.","sources":[{"sourceId":"methods","pages":[75]}]}],"details":[]},{"id":"designs-experiment","topic":"designs","term":"Experiment","aliases":[],"definitions":[{"text":"The process of examining the truth of a statistical hypothesis, relating to some research problem, is known as an Experiment.","sources":[{"sourceId":"methods","pages":[75]}]}],"details":[]},{"id":"designs-exploratory","topic":"designs","term":"Exploratory research","aliases":["formulative research"],"definitions":[{"text":"exploratory research method are also termed as formulative research studied.\nThe main purpose is that of formulate the research problem .three methods are\n1. The survey of concerning literature\n2. The experience survey\n3. The analysis of ‘inside-stimulating","sources":[{"sourceId":"methods","pages":[76]}]},{"text":"Formulating precise questions; navigating the unknown.","sources":[{"sourceId":"architecture","pages":[4]}]}],"details":[{"label":"Formulative design comparison","text":"Flexible design\nJudgmental sampling\nNo pre-determined design\nNo fixed decision about the operational procedures","sources":[{"sourceId":"methods","pages":[77]}]}]},{"id":"designs-diagnostic","topic":"designs","term":"Diagnostic research","aliases":[],"definitions":[{"text":"In diagnostic research study determine the frequency which some thing occur","sources":[{"sourceId":"methods","pages":[76]}]}],"details":[{"label":"Descriptive/diagnostic design comparison","text":"No flexibility\nRandom sampling\nPre-determined design for analysis\nAdvanced decisions","sources":[{"sourceId":"methods","pages":[77]}]}]},{"id":"designs-explanatory","topic":"designs","term":"Explanatory","aliases":[],"definitions":[{"text":"Identifying underlying causes and reasons (the 'Why').","sources":[{"sourceId":"architecture","pages":[4]}]}],"details":[]},{"id":"designs-quasi-experimental","topic":"designs","term":"Quasi-experimental","aliases":["Quasi-experimental"],"definitions":[{"text":"Test for cause/effect relationships without full control","sources":[{"sourceId":"methods","pages":[78]}]},{"text":"Non-equivalent, Time series.","sources":[{"sourceId":"architecture","pages":[9]}]}],"details":[{"label":"Research Designs/Approaches — table row","text":"Time frame\nCurrent or past\n\nDegree of control\nModerate to high\n\nExamples\nGender differences in visual/spatial abilities","sources":[{"sourceId":"methods","pages":[78]}]}],"clarification":{"text":"The table labels this gender-difference example quasi-experimental. Comparing pre-existing groups without an intervention is often causal-comparative/non-experimental; group differences alone do not make a true experiment.","references":[{"title":"KPU: non-equivalent groups designs","url":"https://kpu.pressbooks.pub/psychmethods4e/chapter/non-equivalent-control-group-designs/"}]},"relatedTopics":["experimental"]},{"id":"designs-non-experimental","topic":"designs","term":"Non-Experimental","aliases":[],"definitions":[{"text":"Relies on variables that cannot be manipulated (gender, ethnicity, etc.).\nTypes: Action, Comparative, Developmental, Evaluation, Meta-analysis, Survey.","sources":[{"sourceId":"architecture","pages":[9]}]}],"details":[]},{"id":"designs-cohort-sequential","topic":"designs","term":"Cohort-sequential","aliases":[],"definitions":[{"text":"Examine change in a var. over time in overlapping","sources":[{"sourceId":"methods","pages":[79]}]}],"details":[{"label":"Research Designs/Approaches — table row","text":"Time frame\nFuture\n\nDegree of control\nLow to moderate","sources":[{"sourceId":"methods","pages":[79]}]}],"sourceNote":"The purpose cell ends at “overlapping” in the supplied slide; no missing words have been supplied.","practiceExcludedReason":"The purpose description ends at “overlapping”; no missing completion is invented."},{"id":"historical-historical-research","topic":"historical","term":"Historical Research","aliases":[],"definitions":[{"text":"Historical Research is the systematic collection and evaluation of data to describe, explain, and thereby understand actions or events that occurred sometime in the past. (J.M. Fraenkel & N.E. Wallen)","sources":[{"sourceId":"methods","pages":[81]}]},{"text":"Examines past events to anticipate future effects. Relies on Primary (eyewitness) and Secondary sources. Must pass internal and external criticism.","sources":[{"sourceId":"architecture","pages":[11]}]}],"details":[{"label":"Characteristic, advantages and disadvantages","text":"The unique characteristic of historical research is that it focuses exclusively on past occurrences and events. (J.M. Fraenkel & N.E. Wallen)\n\nAdvantages\nIt is the only research method that can study evidence from the past.\nWider range of evidence than most other methods.\n\nDisadvantages\nThe measures used in other methods to control for threats to internal validity are simply not possible in a historical study.\nBias","sources":[{"sourceId":"methods","pages":[81]}]},{"label":"Uses of historical research","text":"1. To make people aware of what has happened in the past so they may learn from past failures and successes.\n2. To learn how things were done in the past to see if they might be applicable to present-day problems and concerns.\n3. To assist in prediction.\n4. To test hypotheses concerning relationships or trends.","sources":[{"sourceId":"methods","pages":[82]}]},{"label":"Major steps of historical design","text":"I. DEFINING THE PROBLEM\nII. LOCATING RELEVANT SOURCES\nIII. SUMMARIZING INFORMATION OBTAINED FROM HISTORICAL SOURCES\nIV. THE EVALUATION OF HISTORICAL SOURCES","sources":[{"sourceId":"methods","pages":[83,86]}]}]},{"id":"historical-documents","topic":"historical","term":"Documents","aliases":[],"definitions":[{"text":"are written or printed materials that have been produced in some form or another—annual reports, artwork, bills, books, cartoons, circulars, court records, diaries, diplomas, legal records, newspapers, magazines, notebooks, school yearbooks, memos, tests , and so on.","sources":[{"sourceId":"methods","pages":[83]}]}],"details":[]},{"id":"historical-numerical","topic":"historical","term":"Numerical records","aliases":[],"definitions":[{"text":"Numerical, or quantitative, records can be considered either as a separate type of source in and of themselves or as a subcategory of documents—test scores, attendance figures, census reports, school budgets, and the like.","sources":[{"sourceId":"methods","pages":[83]}]}],"details":[]},{"id":"historical-oral","topic":"historical","term":"Oral statements","aliases":[],"definitions":[{"text":"another valuable source of information for the historical researcher lies in the statements people make orally—stories, myths, tales, legends, chants, songs and other forms of oral; expression have been used by people down through the ages to leave a record for future generations.","sources":[{"sourceId":"methods","pages":[84]}]}],"details":[]},{"id":"historical-relics","topic":"historical","term":"Relics","aliases":[],"definitions":[{"text":"is any object whose physical or visual characteristics can provide some information about the past—furniture, artwork, clothing, buildings, monuments, or equipment.","sources":[{"sourceId":"methods","pages":[84]}]}],"details":[]},{"id":"historical-external-criticism","topic":"historical","term":"External Criticism","aliases":[],"definitions":[{"text":"Refers to the genuineness of any and all documents the researcher uses.","sources":[{"sourceId":"methods","pages":[86]}]}],"details":[{"label":"Questions for evaluating genuineness","text":"Who wrote this documents? Was the author living at that time?\nFor what purpose was the document written? For whom was it intended? And why?\nWhen was the document written? Is the date on the document accurate? Could the details describes have actually happened during this time?\nWhere was the document written? Could the details described have occurred in this location?\nUnder what conditions was the document written? Is there any possibility that what was written might have been directly or subtly coerced?\nDo different forms or versions of the document exist?","sources":[{"sourceId":"methods","pages":[86,87]}]}]},{"id":"historical-internal-criticism","topic":"historical","term":"Internal Criticism","aliases":[],"definitions":[{"text":"Once researchers have satisfied themselves that a source document is genuine, they need to determine if the contents of the documents are accurate. This involves what is known as internal criticism. Both the accuracy of the information contained in a document and the truthfulness of the author need to be evaluated.","sources":[{"sourceId":"methods","pages":[87]}]}],"details":[{"label":"With regard to the author of the document","text":"Was the author present at the event he or she is describing? In other words, is the document a primary or a secondary source?\nWas the author a participant in or an observer of the event ?\nWas the author competent to describe the event?","sources":[{"sourceId":"methods","pages":[87]}]}]},{"id":"descriptive-descriptive-research","topic":"descriptive","term":"Descriptive Research","aliases":[],"definitions":[{"text":"The descriptive research is the most popular approach used in research project. Derived from the Latin word de meaning from and scribe meaning write.\n\nDescriptive research includes all studies that purport to present facts concerning the nature and status of anything – a group of persons, a number of objects, a set of conditions, a class of events, a system of thought or any other kind of phenomena which one may wish to study","sources":[{"sourceId":"methods","pages":[89]}]},{"text":"Descriptive research is fact-finding with adequate interpretation. It is something more and beyond just data-gathering; the latter is not reflective thinking nor research. The true meaning of the data collected should be reported from the point of view of the objectives and basic assumption of the project underway.","sources":[{"sourceId":"methods","pages":[89]}]},{"text":"As defined by Best (1963) – Descriptive research describes and interprets what is. It is concerned with conditions of relationships that exist, practices that prevail, beliefs and processes that are going on, effects that are being felt, or trends that are developing.","sources":[{"sourceId":"methods","pages":[89]}]},{"text":"in case of descriptive research study –one those studied which are concerned with describing the characteristics of a particular Individual , or a group.","sources":[{"sourceId":"methods","pages":[76]}]},{"text":"Presenting specific details (the Who, What, Where, and How).","sources":[{"sourceId":"architecture","pages":[4]}]}],"details":[{"label":"Quantitative or qualitative descriptions — legible introductory passage","text":"Descriptive research can be either quantitative or qualitative. It can involve collections of quantitative information that can be tabulated along a continuum in numerical form, such as scores on a test or the number of times a person chooses to use a certain feature of a multimedia program, or it can describe categories of information such as gender or patterns of interaction when using technology in a group situation. Descriptive research involves gathering data that describe events and then organizes, tabulates, depicts, and describes the data collection (Glass & Hopkins, 1984). It often uses visual aids such as graphs and charts to aid the reader in understanding the data distribution. Because the human mind cannot extract the full import of a large mass of raw data, descriptive statistics are very important in reducing the data to manageable form.","sources":[{"sourceId":"methods","pages":[90]}]}]},{"id":"descriptive-normative","topic":"descriptive","term":"Descriptive Normative Method","aliases":[],"definitions":[{"text":"Describes the status of events and people or subjects as they exist. Deals with standardized instruments like mental ability test, stress and personality questionnaire, morale and job satisfaction questionnaire.","sources":[{"sourceId":"methods","pages":[92]}]}],"details":[]},{"id":"descriptive-assessment","topic":"descriptive","term":"Descriptive Assessment Method","aliases":[],"definitions":[{"text":"A fact-finding activity that describes coditions that exist at a particular time such as practices and beliefs. No hypothesis are preposed or tested.","sources":[{"sourceId":"methods","pages":[93]}]}],"details":[]},{"id":"descriptive-trend","topic":"descriptive","term":"Descriptive Trend and Perspective Method","aliases":[],"definitions":[{"text":"This descriptive research id based upon longitudinal consideration of recorded data, indicating what has been happening in the past, what the present situation reveals, and on the basis of these data it projects what is likely to happen in the future.","sources":[{"sourceId":"methods","pages":[93]}]}],"details":[]},{"id":"descriptive-comparative","topic":"descriptive","term":"Descriptive Comparative Method","aliases":[],"definitions":[{"text":"This method provides an explanation about the extent of relationship between two or more variables. The researcher examines the relationships including similarities or differences among several variables.","sources":[{"sourceId":"methods","pages":[94]}]},{"text":"The researcher is knowledgeable about the operation of natural or social forceswhich maybe obtained by watching them analytically at stated intervals in their development over a long periood of time as seen desirable and possible. Also called a genetic method.","sources":[{"sourceId":"methods","pages":[94]}],"label":"Paragraph under the numbered heading"}],"details":[{"label":"Advantages and disadvantages of Comparative Study","text":"Advantages of Comparative Study:\nIntervening variables of comparative study can easily be noted and discerned\nResearch variables can easily be selected.\nComparative results of this study can be known immediately\nComparative method is easily conducted.\n\nDisadvantages of Comparative Study:\nThe findings of the study are very much limited because it cannot show the cause of a change in another variable.\nVariables to be selected are likewise limited.\nIt is difficult to get samples which have the same characteristics or attributes.","sources":[{"sourceId":"methods","pages":[94]}]}],"clarification":{"text":"The yellow paragraph appears mismatched with its heading: longitudinal development is different from the green box's comparison of similarities and differences. The quotations preserve both source passages; they should not be read as equivalent definitions.","references":[{"title":"University of Kansas: designs with comparison groups","url":"https://opentext.ku.edu/assessmentevaluationhighered/chapter/chapter-14-designs-involving-comparison-groups/"}]}},{"id":"experimental-experimental-design","topic":"experimental","term":"Experimental Design","aliases":[],"definitions":[{"text":"problem solving approach that the study is described in the future on what will be when variables are carefully controlled or manipulated\n\ncan be a basic, applied, or developmental research\n\na research wherein a researcher manipulates and controls one or more independent variables for variation concomitant to the manipulation of the dependent variable\n\nused to find out what caused the change in the characteristics or behavior of the subjects and what change or effect has been made then","sources":[{"sourceId":"methods","pages":[96]}]},{"text":"Test for cause/effect relationships","sources":[{"sourceId":"methods","pages":[78]}]},{"text":"Guided strictly by hypotheses; involves direct manipulation and control of variables to prove or disprove statements.","sources":[{"sourceId":"architecture","pages":[8]}]}],"details":[{"label":"Distinguishing Features","text":"It is usually involves two groups - an experimental group and a control group\nExperimental group – exposed to the influence of a factor - an intervention or treatment under consideration\nControl group – not exposed to the same factor to which experimental group is exposed to, or it receives a different treatment, or it is left to its usual way of doing things\nThe control and manipulation of variables constitute the essential feature of experimental design\nThe only design wherein the invest – harvest principle can be attained.\nIt is expected to reveal cause and effect relationship even if the experiment conducted in the field or laboratory\nIt is given priority by research institutions in giving of research grants-in-aid","sources":[{"sourceId":"methods","pages":[97]}]},{"label":"7 Ms","text":"Manpower\nMoney\nMethods\nMaterials\nMachinery\nMoment of time\nMarketing","sources":[{"sourceId":"methods","pages":[98]}]},{"label":"Experimental Plan","text":"1. Determining the experimental problem or topic\n2. Surveying related literature and studies\n3. Formulating the hypothesis or hypotheses\n4. Identifying the experimental variables\n5. Select the appropriate experimental design\n6. Selecting the sample\n7. Selecting or constructing appropriate instruments to measure the results of the experiment\n8. Conducting the experiment\n   History\n   Maturation\n   Testing\n   Biases in the selection of the respondents\n   Experimental mortality\n   Interaction effects\n9. Measuring the results and applying statistical procedures\n10. Writing the reports of the experiment","sources":[{"sourceId":"methods","pages":[99]}]},{"label":"True Experimental","text":"Pretest-posttest, Solomon four-group.","sources":[{"sourceId":"architecture","pages":[9]}]},{"label":"Pre-experimental","text":"One-shot case, One group pretest.","sources":[{"sourceId":"architecture","pages":[9]}]}],"clarification":{"text":"The independent variable is manipulated; the dependent variable is ordinarily measured as the response. The slide's dependent-variable wording should not be used as a general definition.","references":[{"title":"BCcampus: experiment basics and validity","url":"https://opentextbc.ca/researchmethods/chapter/experiment-basics/"}]}},{"id":"experimental-posttest-only","topic":"experimental","term":"Posttest only design","aliases":[],"definitions":[{"text":"Also known as one shot case study\ninvolves just one group of subjects which is exposed to an intervention or treatment. After sometime it is given a posttest or is subject for observation.","sources":[{"sourceId":"methods","pages":[100]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[100]}],"diagram":"Experimental Group    X    O"}]},{"id":"experimental-one-group-pretest-posttest","topic":"experimental","term":"The one-group pretest-posttest design","aliases":[],"definitions":[{"text":"As to posttest-only, this design is without a control group.\nHowever, a pretest or baseline observation (O1) which allows the investigator to determine the effects of the treatment by comparing pretest and posttest (O2) results.","sources":[{"sourceId":"methods","pages":[100]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[100]}],"diagram":"Experimental Group    O₁    X    O₂"}]},{"id":"experimental-static-group","topic":"experimental","term":"The static-group comparison design","aliases":[],"definitions":[{"text":"It has a control or comparison group.\nExperimental group is exposed to an intervention or treatment (X) which is derived of the control group.\nAfter some time the experimental group and the control group are observed","sources":[{"sourceId":"methods","pages":[101]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[101]}],"diagram":"Experimental Group    X    O\nControl Group              O"}]},{"id":"experimental-pretest-posttest-control","topic":"experimental","term":"The pretest-posttest control group design","aliases":[],"definitions":[{"text":"this design involves the random assignment of subjects from a single population the experimental and the control groups.\nthis two groups receive initial observations or pretests (O1 & O3) and posttest (O2 & O4) to determine the differences.","sources":[{"sourceId":"methods","pages":[101]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[101]}],"diagram":"R Experimental Group    O₁    X    O₂\nR Control Group         O₃         O₄"}]},{"id":"experimental-posttest-control","topic":"experimental","term":"The posttest-only control group design","aliases":[],"definitions":[{"text":"Involves both the experimental and the control groups which were created through random assignment (R) subjects from a study population.\nboth are not given pretest; both receives posttest after the experimental group has been exposed to intervention or","sources":[{"sourceId":"methods","pages":[102]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[102]}],"diagram":"R Experimental Group    X    O₁\nR Control Group              O₂"}],"sourceNote":"The description ends at the quoted word in the supplied slide; no missing ending has been supplied.","practiceExcludedReason":"The source description ends at “or”; retain the text as notes, without scoring an incomplete definition."},{"id":"experimental-solomon","topic":"experimental","term":"The Solomon four-group design","aliases":[],"definitions":[{"text":"The subjects are randomly assigned to four groups.\nTwo groups are experimental and the other two groups are control groups.\nOne experimental group and one control group is subject to pretest, and all four are subject to posttest.","sources":[{"sourceId":"methods","pages":[102]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[102]}],"diagram":"R Experimental Group    O₁    X    O₂\nR Control Group         O₃         O₄\nR Experimental Group          X    O₅\nR Control Group                    O₆"}]},{"id":"experimental-non-equivalent","topic":"experimental","term":"The non-equivalent control group design","aliases":[],"definitions":[{"text":"involves two groups which are the experimental and the control groups.\nlike pretest-posttest control group design both experimental and control group undergo pretest and posttest, the only difference is that, in this design the assignment of subjects into these groups is not done","sources":[{"sourceId":"methods","pages":[103]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[103]}],"diagram":"Experimental Group    O₁    X    O₂\nControl Group         O₃    X    O₄"}],"sourceNote":"The description ends at the quoted word in the supplied slide; no missing ending has been supplied.","clarification":{"text":"This conflicts with the text's control-group comparison. A conventional untreated comparison row does not receive the intervention X. Do not copy the printed extra X into a corrected comparison diagram.","references":[{"title":"University of Kansas: designs with comparison groups","url":"https://opentext.ku.edu/assessmentevaluationhighered/chapter/chapter-14-designs-involving-comparison-groups/"}]},"practiceExcludedReason":"The defining assignment sentence is clipped and its diagram also contains a treatment-symbol error. Retain the quotation and clarification without reconstructing the definition."},{"id":"experimental-separate-sample","topic":"experimental","term":"Separate Sample pretest-posttest group design","aliases":[],"definitions":[{"text":"involves two groups, the creation of which was done by a random selection (R) of samples.\none group is subject to a baseline pretest (O1), and another group is used for the posttest measurement (O2).","sources":[{"sourceId":"methods","pages":[103]}]}],"details":[],"clarification":{"text":"The separate-sample sketch has ambiguous X placement and mixes random selection wording with R notation. The bank tests the readable prose and does not score an exact reconstruction of that ambiguous sketch.","references":[{"title":"University of Kansas: designs with comparison groups","url":"https://opentext.ku.edu/assessmentevaluationhighered/chapter/chapter-14-designs-involving-comparison-groups/"}]}},{"id":"experimental-time-series","topic":"experimental","term":"The time-series design","aliases":[],"definitions":[{"text":"an improvement of the one-group pretest-posttest design because it has the advantage of repeated observations before and after the intervention or treatment has been introduced to the study group.\nthe more number of pretest and posttest the better it will be for study.","sources":[{"sourceId":"methods","pages":[104]}]}],"details":[{"label":"Notation as printed on the slide","text":"","sources":[{"sourceId":"methods","pages":[104]}],"diagram":"Experimental Group    O₁ O₂ O₃ O₄ X O₅ O₆ O₇ O₈"}]},{"id":"experimental-internal-validity","topic":"experimental","term":"Internal validity","aliases":[],"definitions":[{"text":"changes attributed to independent variable","sources":[{"sourceId":"architecture","pages":[9]}]}],"details":[]},{"id":"experimental-external-validity","topic":"experimental","term":"External validity","aliases":[],"definitions":[{"text":"changes attributed to extraneous variables","sources":[{"sourceId":"architecture","pages":[9]}]}],"details":[],"clarification":{"text":"External validity concerns generalization beyond the studied people/settings. Extraneous variables and alternative causes concern internal validity. The sidebar conflates these concepts.","references":[{"title":"BCcampus: experiment basics and validity","url":"https://opentextbc.ca/researchmethods/chapter/experiment-basics/"}]},"practiceExcludedReason":"The source describes extraneous variables rather than generalizability; retain the quotation and correction without scoring the erroneous definition."},{"id":"approaches-basic","topic":"approaches","term":"Basic Research","aliases":["pure research"],"definitions":[{"text":"Goal: Advance fundamental knowledge.\nFocus: Refuting/supporting theories of how the world operates.\nPrimary Consumer: The academic community.","sources":[{"sourceId":"architecture","pages":[5]}]}],"details":[]},{"id":"approaches-applied","topic":"approaches","term":"Applied Research","aliases":[],"definitions":[{"text":"Goal: Solve specific problems or accomplish tasks.\nFocus: Immediate practical use and descriptive clarity.\nPrimary Consumer: Practitioners, decision-makers, teachers.","sources":[{"sourceId":"architecture","pages":[5]}]}],"details":[]},{"id":"approaches-action","topic":"approaches","term":"Action Research","aliases":[],"definitions":[{"text":"Conducted by/for practitioners to immediately refine their own actions.","sources":[{"sourceId":"architecture","pages":[6]}]}],"details":[]},{"id":"approaches-impact","topic":"approaches","term":"Impact Assessment","aliases":[],"definitions":[{"text":"Estimating the consequences of a planned change or policy.","sources":[{"sourceId":"architecture","pages":[6]}]}],"details":[]},{"id":"approaches-evaluation","topic":"approaches","term":"Evaluation","aliases":["formative","summative","Descriptive Evaluative Method"],"definitions":[{"text":"Establishing value judgments (Formative = ongoing monitoring; Summative = final outcomes).","sources":[{"sourceId":"architecture","pages":[6]}]},{"text":"This study judges the goodness of an existing program. It is directed to whether or not a particular program achieved its goal or not. Value judgement in terms of effectiveness, desirability, or social validity.","sources":[{"sourceId":"methods","pages":[92]}]}],"details":[],"relatedTopics":["descriptive"]},{"id":"approaches-cross-sectional","topic":"approaches","term":"Cross-Sectional","aliases":[],"definitions":[{"text":"A single, fixed time point. Cost-effective but cannot capture the change process.","sources":[{"sourceId":"architecture","pages":[6]}]}],"details":[]},{"id":"approaches-longitudinal","topic":"approaches","term":"Longitudinal","aliases":[],"definitions":[{"text":"Multiple time points over an extended period (Time series, panel, cohort). Costly, but powerful for analyzing change.","sources":[{"sourceId":"architecture","pages":[6]}]}],"details":[]},{"id":"approaches-quantitative","topic":"approaches","term":"Quantitative","aliases":["quantitative research"],"definitions":[{"text":"Deductive reasoning, objective reality, numbers, and statistical analysis.","sources":[{"sourceId":"architecture","pages":[7]}]}],"details":[]},{"id":"approaches-qualitative","topic":"approaches","term":"Qualitative","aliases":["qualitative research","The Naturalistic Lens"],"definitions":[{"text":"Inductive reasoning, subjective reality, human behavior, and natural settings.","sources":[{"sourceId":"architecture","pages":[7]}]},{"text":"Discover potential relationships; descriptive.","sources":[{"sourceId":"methods","pages":[79]}]},{"text":"Focuses on in-depth, subjective descriptions of human complexity in natural settings, unbound by existing theories.","sources":[{"sourceId":"architecture","pages":[10]}]}],"details":[{"label":"Limitations as printed on the slide","text":"Reductionist by nature\nHighly subjective\nInherently limited to small sample sizes","sources":[{"sourceId":"architecture","pages":[10]}]},{"label":"Orientation & Overview","text":"Determining what is salient about the phenomenon.","sources":[{"sourceId":"architecture","pages":[10]}]},{"label":"Focused Exploration","text":"In-depth scrutiny based on the outcomes of Phase 1.","sources":[{"sourceId":"architecture","pages":[10]}]},{"label":"Confirmation & Closure","text":"Establishing trustworthiness by verifying findings with participants.","sources":[{"sourceId":"architecture","pages":[10]}]}],"relatedTopics":[]},{"id":"approaches-mixed","topic":"approaches","term":"Mixed Methods","aliases":[],"definitions":[{"text":"Combining paradigms for superior evidence and comprehensive insight.","sources":[{"sourceId":"architecture","pages":[7]}]}],"details":[]},{"id":"approaches-survey","topic":"approaches","term":"Survey","aliases":["Descriptive Survey Method"],"definitions":[{"text":"Uses interviews and questionnaires to judge behavior with intense precision across one or multiple groups.","sources":[{"sourceId":"architecture","pages":[8]}]},{"text":"Assess opinions or characteristics that exist at a given time.","sources":[{"sourceId":"methods","pages":[79]}]},{"text":"Survey derived from the Latin sur or super which means “above” or “view” and vey which means “to look” or “to see”. Survey means “to look over or beyond”. Ussually used by graduate and undergraduate students when they attemp to analyze, interpret, and report status od their subject matter or problem","sources":[{"sourceId":"methods","pages":[92]}]}],"details":[],"relatedTopics":["descriptive"]},{"id":"approaches-correlational","topic":"approaches","term":"Correlational","aliases":["Non-experimental - correlational","Descriptive Correlational Method"],"definitions":[{"text":"Tests relationships between 2+ variables to predict future conditions (Note: Correlation does not equate to causation).","sources":[{"sourceId":"architecture","pages":[8]}]},{"text":"Examine relationship between two variables","sources":[{"sourceId":"methods","pages":[78]}]},{"text":"Examine relationship bet 2 var. where 1 is measured later.","sources":[{"sourceId":"methods","pages":[79]}]},{"text":"Used to determine whether or not there is a relationship that exist between two or more quantifiable variables, and if there is, to what extent or degree the relationship is determined, the researcher must identify whether such relationship is positive (+) or negative (-) and the degree or extent (strength) of relationship.","sources":[{"sourceId":"methods","pages":[92]}]}],"details":[{"label":"Research Designs/Approaches — page 78","text":"Time frame\nCurrent (cross-sectional) or past\n\nDegree of control\nLow to medium\n\nExamples\nRelationship between studying style and grade point average.","sources":[{"sourceId":"methods","pages":[78]}]},{"label":"Research Designs/Approaches — page 79","text":"Time frame\nFuture - predictive\n\nDegree of control\nLow to moderate\n\nExamples\nRelationship bet history of depression & development of cancer.","sources":[{"sourceId":"methods","pages":[79]}]}],"relatedTopics":["designs","descriptive"]},{"id":"approaches-causal-comparative","topic":"approaches","term":"Causal-Comparative","aliases":["Ex post facto","Descriptive Ex-Post Facto Method"],"definitions":[{"text":"Identifies how different groups are affected by the same circumstance without manipulating variables.","sources":[{"sourceId":"architecture","pages":[8]}]},{"text":"Examine the effect of past event on current functioning.","sources":[{"sourceId":"methods","pages":[78]}]},{"text":"This type of research is also known as causal-comparative research of after-the-fact research. In this method, the researcher is trying to establish a causal effect between existing conditions.","sources":[{"sourceId":"methods","pages":[93]}]}],"details":[],"relatedTopics":["designs","descriptive"]},{"id":"approaches-phenomenology","topic":"approaches","term":"Phenomenology","aliases":[],"definitions":[{"text":"Focuses on lived experiences. Assumes each person has their own subjective reality. Contains no rigidly defined steps to preserve creativity.","sources":[{"sourceId":"architecture","pages":[11]}]}],"details":[]},{"id":"approaches-ethnography","topic":"approaches","term":"Ethnography","aliases":[],"definitions":[{"text":"Focuses on cultural characteristics. Requires the researcher to immerse themselves in the culture and utilize key informants.","sources":[{"sourceId":"architecture","pages":[11]}]}],"details":[]},{"id":"approaches-case-study","topic":"approaches","term":"Case Study","aliases":["Descriptive Case study Method"],"definitions":[{"text":"An in-depth observation of a specific person, group, or event over time. Utilizes interviews, field notes, and direct observation.","sources":[{"sourceId":"architecture","pages":[11]}]},{"text":"A case study is an intensive and descriptive analyss of a single subject. It examines a social units as a whole, and the unit may be a single typical individual. It examines a social unit as a whole, and the unit may be a single typical individual, a family, a social group, a social institution or a community","sources":[{"sourceId":"methods","pages":[93]}]}],"details":[],"relatedTopics":["descriptive"]},{"id":"approaches-triangulation","topic":"approaches","term":"Triangulation","aliases":[],"definitions":[{"text":"Corroborating results across different methods","sources":[{"sourceId":"architecture","pages":[12]}]}],"details":[]},{"id":"approaches-expansion","topic":"approaches","term":"Expansion","aliases":[],"definitions":[{"text":"Broadening the overarching range of inquiry","sources":[{"sourceId":"architecture","pages":[12]}]}],"details":[]},{"id":"approaches-development","topic":"approaches","term":"Development","aliases":[],"definitions":[{"text":"Using findings from one method to inform the other","sources":[{"sourceId":"architecture","pages":[12]}]}],"details":[]},{"id":"approaches-complementarity","topic":"approaches","term":"Complementarity","aliases":[],"definitions":[{"text":"Clarifying the results of one method with the other","sources":[{"sourceId":"architecture","pages":[12]}]}],"details":[]},{"id":"approaches-initiation","topic":"approaches","term":"Initiation","aliases":[],"definitions":[{"text":"Discovering paradoxes to re-frame research questions","sources":[{"sourceId":"architecture","pages":[12]}]}],"details":[]},{"id":"approaches-mixed-method","topic":"approaches","term":"Mixed Method","aliases":[],"definitions":[{"text":"paradigms split by phase","sources":[{"sourceId":"architecture","pages":[12]}]}],"details":[]},{"id":"approaches-mixed-model","topic":"approaches","term":"Mixed Model","aliases":[],"definitions":[{"text":"paradigms mixed within a single stage","sources":[{"sourceId":"architecture","pages":[12]}]}],"details":[]},{"id":"digital-e-research","topic":"digital","term":"e-Research","aliases":[],"definitions":[{"text":"Collaboration, advanced visualization, and global research data management.","sources":[{"sourceId":"architecture","pages":[13]}]}],"details":[{"label":"Participants — Traditional","text":"Individual/local teams","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Participants — e-Research","text":"Diversely skilled, distributed global teams.","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Data — Traditional","text":"Locally generated and stored","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Data — e-Research","text":"Globally generated, stored, and accessible.","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Computation — Traditional","text":"Run on researcher’s own local computers","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Computation — e-Research","text":"Large-scale, on-demand computation and shared instruments.","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Networking — Traditional","text":"Not reliant on the internet","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Networking — e-Research","text":"Entirely reliant on internet and middleware.","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Dissemination — Traditional","text":"Print publications and physical conferences","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"Dissemination — e-Research","text":"Websites and specialized web portals.","sources":[{"sourceId":"architecture","pages":[14]}]},{"label":"The Input","text":"Purpose & Goals (Exploratory, Descriptive, Explanatory)","sources":[{"sourceId":"architecture","pages":[15]}]},{"label":"The Engine","text":"Methodologies (Quantitative, Qualitative, Mixed) interacting with Time Dimensions (Cross-sectional, Longitudinal)","sources":[{"sourceId":"architecture","pages":[15]}]},{"label":"The Infrastructure","text":"The e-Research Cyberinfrastructure Stack (enabling global scale)","sources":[{"sourceId":"architecture","pages":[15]}]},{"label":"The Output","text":"Translating inquiry into evidence-based practice and societal mobilization","sources":[{"sourceId":"architecture","pages":[15]}]}]},{"id":"digital-middleware","topic":"digital","term":"Middleware","aliases":[],"definitions":[{"text":"Software providing standard community tools and services for seamless knowledge sharing.","sources":[{"sourceId":"architecture","pages":[13]}]}],"details":[]},{"id":"digital-grid","topic":"digital","term":"Grid","aliases":[],"definitions":[{"text":"The collection of data repositories, specialized scientific equipment, and pooled computing power.","sources":[{"sourceId":"architecture","pages":[13]}]}],"details":[]},{"id":"digital-cyberinfrastructure","topic":"digital","term":"Cyberinfrastructure","aliases":[],"definitions":[{"text":"The overarching computing and network environments that enable virtual e-science communities.","sources":[{"sourceId":"architecture","pages":[13]}]}],"details":[]},{"id":"reliability-test-retest","topic":"reliability","term":"Test-retest method","aliases":[],"definitions":[{"text":"In this method, the same instrument is administered twice to the same group of subjects and the correlation coefficient is determined.","sources":[{"sourceId":"methods","pages":[28]}]},{"text":"Temporal stability across administrations.","sources":[{"sourceId":"reliability","pages":[2]}],"label":"Overview"},{"text":"The identical assessment instrument is administered twice to the same cohort over a predetermined time interval.\nWhen participant scores are expressed as ordinal rankings, Spearman's rank correlation coefficient calculates the consistency of ranking stability.","sources":[{"sourceId":"reliability","pages":[3]}]}],"details":[{"label":"Formula and symbols","text":"Where D represents rank differences and N is sample size.","sources":[{"sourceId":"reliability","pages":[3]}],"formula":"rₛ = 1 − (6 Σ D²) / (N³ − N)"},{"label":"Worked example","text":"Evaluation (N = 5)\nDenominator: 5³ − 5 = 125 − 5 = 120\nNumerator: 6 × Σ D² = 6 × 2 = 12\nFraction: 12 ÷ 120 = 0.10\nrs = 1 − 0.10 = 0.90\nHigh temporal rank stability.","sources":[{"sourceId":"reliability","pages":[4]}],"table":{"headers":["Student","Rank 1","Rank 2","D (Diff)","D²"],"rows":[["A",1,1,0,0],["B",2,3,-1,1],["C",3,2,"+1",1],["D",4,4,0,0],["E",5,5,0,0],["Total Σ D²","","","",2]]}}]},{"id":"reliability-parallel-forms","topic":"reliability","term":"Parallel-forms method","aliases":["Parallel or equivalent forms"],"definitions":[{"text":"Parallel or equivalent forms of a test may be administered of the group of subjects, and the paired observations correlated","sources":[{"sourceId":"methods","pages":[28]}]},{"text":"Equivalence across alternate instruments.","sources":[{"sourceId":"reliability","pages":[2]}],"label":"Overview"},{"text":"Two equivalent test forms with identical blueprints are administered to the same group to gauge form equivalence.\nPaired observation scores are correlated using the Pearson product-moment correlation formula.","sources":[{"sourceId":"reliability","pages":[5]}]}],"details":[{"label":"Formula and symbols","text":"Where X is Form A and Y is Form B.","sources":[{"sourceId":"reliability","pages":[5]}],"formula":"r = [N Σ XY − (Σ X)(Σ Y)] / √([N Σ X² − (Σ X)²][N Σ Y² − (Σ Y)²])"},{"label":"Worked example","text":"Formula Substitution\nNumerator: 5(228) − (32)(32) = 1140 − 1024 = 116\nDenominator: √[(1170 − 1024)(1130 − 1024)]\nDenominator: √(146 × 106) = √15476 ≈ 124.40\nr = 116 ÷ 124.40 = 0.93\nHigh parallel-form equivalence.","sources":[{"sourceId":"reliability","pages":[6]}],"table":{"headers":["Student","Form A (X)","Form B (Y)","X²","Y²","XY"],"rows":[[1,10,9,100,81,90],[2,8,8,64,64,64],[3,6,7,36,49,42],[4,5,4,25,16,20],[5,3,4,9,16,12],["Total",32,32,234,226,228]]}}]},{"id":"reliability-split-half","topic":"reliability","term":"Split-half method","aliases":[],"definitions":[{"text":"The test in this method may be administered twice, but the test items are divided into two values.","sources":[{"sourceId":"methods","pages":[28]}]},{"text":"Spearman-Brown internal test partitioning.","sources":[{"sourceId":"reliability","pages":[2]}],"label":"Overview"},{"text":"A single test is split into equal halves (commonly odd vs. even numbered questions) and correlated.\nBecause dividing test length underestimates full test reliability, the Spearman-Brown prophecy formula restores full-scale estimation.","sources":[{"sourceId":"reliability","pages":[7]}]}],"details":[{"label":"Formula and symbols","text":"Where rwt is whole-test reliability and rht is half-test correlation.","sources":[{"sourceId":"reliability","pages":[7]}],"formula":"rwt = 2(rht) / (1 + rht)"},{"label":"Worked example","text":"Step 1\nOdd-Even Partition\nCorrelated half-test correlation rht = 0.70.\n\nStep 2\nFormula Substitution\nrwt = 2(0.70) / (1 + 0.70).\n\nStep 3\nFraction Resolution\n1.40 ÷ 1.70 = 0.824.\n\nCalculated Whole-Test Reliability\nSpearman-Brown correction increases reliability from 0.70 to 0.82.\nrwt = 0.82","sources":[{"sourceId":"reliability","pages":[8]}]}],"clarification":{"text":"Split-half reliability ordinarily uses one administration split into comparable halves. The supplied reliability deck page 7 uses that single-test approach. Two administrations are not required for split-half estimation.","references":[{"title":"UConn: instrument reliability","url":"https://researchbasics.education.uconn.edu/instrument_reliability/"},{"title":"ETS: reliability from comparable test halves","url":"https://www.ets.org/research/policy_research_reports/publications/report/1950/ikve.html"}]}},{"id":"reliability-internal-consistency","topic":"reliability","term":"Internal-consistency method","aliases":[],"definitions":[{"text":"This method is used with psychological test which consist of dichotomously scored items.","sources":[{"sourceId":"methods","pages":[28]}]}],"details":[]},{"id":"frameworks-construct","topic":"frameworks","term":"constructs","aliases":["construct"],"definitions":[{"text":"specific and well-defined concepts","sources":[{"sourceId":"methods","pages":[44]}]}],"details":[]},{"id":"approaches-formative","topic":"approaches","term":"Formative","aliases":["formative evaluation"],"definitions":[{"text":"ongoing monitoring","sources":[{"sourceId":"architecture","pages":[6]}]}],"details":[]},{"id":"approaches-summative","topic":"approaches","term":"Summative","aliases":["summative evaluation"],"definitions":[{"text":"final outcomes","sources":[{"sourceId":"architecture","pages":[6]}]}],"details":[]},{"id":"reliability-spearman","topic":"reliability","term":"Spearman's rank correlation coefficient","aliases":["Spearman rank correlation","Spearman rank formula"],"definitions":[{"text":"When participant scores are expressed as ordinal rankings, Spearman's rank correlation coefficient calculates the consistency of ranking stability.","sources":[{"sourceId":"reliability","pages":[3]}]}],"details":[]},{"id":"reliability-pearson","topic":"reliability","term":"Pearson product-moment correlation","aliases":["Pearson correlation"],"definitions":[{"text":"Two equivalent test forms with identical blueprints are administered to the same group to gauge form equivalence.\nPaired observation scores are correlated using the Pearson product-moment correlation formula.","sources":[{"sourceId":"reliability","pages":[5]}]}],"details":[]},{"id":"reliability-spearman-brown","topic":"reliability","term":"Spearman-Brown prophecy formula","aliases":["Spearman-Brown correction"],"definitions":[{"text":"Because dividing test length underestimates full test reliability, the Spearman-Brown prophecy formula restores full-scale estimation.","sources":[{"sourceId":"reliability","pages":[7]}]}],"details":[]},{"id":"reliability-kr20","topic":"reliability","term":"KR-20","aliases":["Kuder-Richardson Formula 20","KR20"],"definitions":[{"text":"Homogeneity across dichotomous items.","sources":[{"sourceId":"reliability","pages":[2]}],"label":"Overview"},{"text":"KR-20 evaluates item homogeneity across tests containing dichotomously scored items (scored right/wrong or 1/0).\nIt calculates test variance against the sum of individual item variances across all test questions.","sources":[{"sourceId":"reliability","pages":[9]}]}],"details":[{"label":"Formula and symbols","text":"Where N = test items, p = pass rate, and q = fail rate (1 − p).","sources":[{"sourceId":"reliability","pages":[9]}],"formula":"Rₓₓ = [N / (N − 1)] [(SD² − Σ pᵢqᵢ) / SD²]"},{"label":"Worked example","text":"Item Count (N)\n10\nTotal Variance (SD²)\n4.00\nItem Variances (Σ pq)\n1.60\n\n1. Scale Multiplier: [N / (N − 1)] = 10 ÷ 9 = 1.111\n2. Variance Ratio: [(4.00 − 1.60) / 4.00] = 2.40 ÷ 4.00 = 0.600\n3. Product: 1.111 × 0.600 = 0.667\nKR-20 RELIABILITY\n0.67","sources":[{"sourceId":"reliability","pages":[10]}]}]}]};
